<?php
declare(strict_types=1);require_once __DIR__.'/../api/pesapal_status.php';
$config=require __DIR__.'/../config/config.php';$method=$_SERVER['REQUEST_METHOD'];$payload=$method==='POST'?(json_decode(file_get_contents('php://input'),true)??$_POST):$_GET;$tracking=trim((string)($payload['OrderTrackingId']??''));$ref=trim((string)($payload['OrderMerchantReference']??''));
if(!$tracking){http_response_code(400);echo json_encode(['orderNotificationType'=>'IPNCHANGE','orderTrackingId'=>'','orderMerchantReference'=>$ref,'status'=>500]);exit;}
try{$details=getStatus($tracking,$config);$status=strtoupper((string)($details['payment_status_description']??'PENDING'));$pdo=new PDO('sqlite:'.__DIR__.'/../data/donations.sqlite');$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$s=$pdo->prepare('UPDATE donations SET status=?,tracking_id=?,updated_at=? WHERE merchant_reference=? OR tracking_id=?');$s->execute([$status,$tracking,date('c'),$ref,$tracking]);http_response_code(200);echo json_encode(['orderNotificationType'=>'IPNCHANGE','orderTrackingId'=>$tracking,'orderMerchantReference'=>$ref,'status'=>200]);}catch(Throwable $e){http_response_code(500);echo json_encode(['orderNotificationType'=>'IPNCHANGE','orderTrackingId'=>$tracking,'orderMerchantReference'=>$ref,'status'=>500]);}
